from pathlib import Path
root = Path(r"C:\Users\JUAN009\Desktop\PortaFlores")
index = root / "index.html"
css = root / "css" / "style.css"
html = index.read_text(encoding='utf-8')
html = html.replace('<h2>Código en GitHub <span class="arrow-accent">↗</span></h2>', '<h2>Código y proyectos <span class="arrow-accent">↗</span></h2>', 1)
index.write_text(html, encoding='utf-8')
css_text = css.read_text(encoding='utf-8')
css_text += '''\n\n/* Visual refinement: match the generated Código y proyectos mockup */\n.code-projects-page { padding: 4px 2px 10px; }\n.code-projects-header { margin-bottom: 28px; align-items: center; }\n.code-projects-header h2 { font-size: clamp(38px, 4.6vw, 58px); letter-spacing: -.065em; }\n.code-projects-header p { font-size: 14px; margin-top: 12px; max-width: 760px; }\n.github-profile-btn { padding: 14px 20px; border-radius: 11px; background: #fff; box-shadow: 0 5px 15px rgba(236,0,140,.08); }\n.code-metrics { gap: 17px; margin-bottom: 17px; }\n.code-metric { min-height: 102px; padding: 20px 24px; border-radius: 18px; gap: 17px; }\n.metric-icon { width: 50px; height: 50px; flex-basis: 50px; font-size: 19px; }\n.code-metric strong { font-size: 30px; }\n.code-metric-yellow strong { font-size: 22px; }\n.code-metric span:not(.metric-icon) { font-size: 12px; margin-top: 6px; }\n.code-projects-grid { gap: 16px; }\n.code-project-card { min-height: 342px; padding: 17px; border-radius: 18px; box-shadow: 0 6px 20px rgba(20,20,30,.035); }\n.code-project-card:hover { transform: translateY(-4px); box-shadow: 0 16px 32px rgba(20,20,30,.09); }\n.code-project-card h3 { font-size: 19px; margin-top: 12px; }\n.code-project-card p { font-size: 12px; height: 32px; }\n.project-tech-tags { margin-top: 9px; }\n.project-tech-tags span { padding: 6px 10px; font-size: 10px; }\n.mini-preview { height: 145px; margin-top: 15px; padding: 14px; border-radius: 11px; }\n.mini-preview strong { font-size: 17px; left: 15px; bottom: 21px; }\n.mini-hacki strong { font-size: 12px; bottom: 47px; }\n.mini-hacki .mini-input { bottom: 13px; padding: 6px 8px; }\n.mini-contax strong { font-size: 12px; top: 15px; }\n.mini-donut { width: 64px; height: 64px; top: 34px; right: 28px; }\n.mini-deli i, .mini-portfolio i { font-size: 42px; right: 32px; bottom: 30px; }\n.project-links { margin-top: 14px; gap: 13px; }\n.project-links a { font-size: 11px; }\n@media (max-width: 1050px) { .code-projects-header h2 { font-size: 42px; } .code-project-card { min-height: 325px; } }\n'''
css.write_text(css_text, encoding='utf-8')
print('Refinamiento visual aplicado a Código y proyectos.')
